import React from 'react';

const QuoteSection = () => {
    return (
        <section className="bg-white w-full py-[60px] md:py-[100px] border-b border-[#E5E7EB]">
            <div className="container mx-auto max-w-[1446px] px-4 md:px-[80px]">
                <div className="relative w-full rounded-[24px] md:rounded-[40px] overflow-hidden shadow-xl aspect-[16/10] md:aspect-auto md:h-[650px]">
                    {/* Background Image with Overlay */}
                    <div className="absolute inset-0">
                        <img
                            src="/images/9.png"
                            alt="Workshop"
                            className="w-full h-full object-cover"
                        />
                        <div className="absolute inset-0 bg-black/40 md:bg-black/30"></div>
                    </div>

                    {/* Quote Content */}
                    <div className="relative h-full flex flex-col items-center justify-center px-6 md:px-20 text-center text-white">
                        <div className="max-w-[1000px] mx-auto">
                            <h2 className="font-serif text-[22px] xs:text-[28px] sm:text-[36px] md:text-[44px] lg:text-[52px] leading-tight md:leading-[1.2] font-semibold mb-8 md:mb-12">
                                "Voice Control is a groundbreaking guide to mastering vocal power, emotional regulation, and authentic presence essential reading for anyone who speaks to be heard."
                            </h2>

                            <div className="flex flex-col items-center gap-2">
                                <p className="font-sans font-bold text-[14px] md:text-[18px] tracking-widest uppercase">
                                    — SEVIL VELSHA
                                </p>
                                <p className="font-sans text-[12px] md:text-[14px] opacity-80 uppercase tracking-wider">
                                    Speaker • Coach, Author of Voice Control
                                </p>
                            </div>
                        </div>

                        {/* Carousel Dots */}
                        <div className="absolute bottom-6 md:bottom-12 flex items-center gap-2 md:gap-3">
                            {[1, 2, 3, 4, 5].map((item, index) => (
                                <div
                                    key={index}
                                    className={`w-1.5 h-1.5 md:w-2 md:h-2 rounded-full transition-all duration-300 ${index === 0 ? 'bg-white scale-125' : 'bg-white/40'}`}
                                ></div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default QuoteSection;
